thread_local! {
    /// Test-only clock override (ns). `None` → the fixed default. Lets
    /// pacing / TTL / per-day-cap tests advance time deterministically.
    static TEST_MOCK_TIME: RefCell<Option<u64>> = const { RefCell::new(None) };
}

#[cfg(not(target_arch = "wasm32"))]
fn set_mock_time(ns: Option<u64>) {
    TEST_MOCK_TIME.with(|c| *c.borrow_mut() = ns);
}

fn current_time() -> u64 {
    #[cfg(target_arch = "wasm32")]
    {
        ic_cdk::api::time()
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        TEST_MOCK_TIME.with(|c| c.borrow().unwrap_or(1_700_000_000_000_000_000))
    }
}

fn recompute_pool_info() {
    let mut total_vp: u64 = 0;
    let mut active_count = 0;
    POOL_NEURONS.with(|map| {
        for entry in map.borrow().iter() {
            let n = entry.value();
            if n.status == PoolStatus::Active {
                total_vp = total_vp.saturating_add(n.voting_power);
                active_count += 1;
            }
        }
    });
    CACHED_POOL_INFO.with(|cell| {
        let mut info = cell.borrow_mut();
        info.total_pool_voting_power = total_vp;
        info.active_count = active_count;
        info.updated_at = current_time();
    });
}

