// These mirror the *real* CMC candid exactly (rs/nns/cmc/cmc.did):
//   NotifyTopUpArg    = record { block_index : nat64; canister_id : principal }
//   NotifyTopUpResult = variant { Ok : nat (Cycles); Err : NotifyError }
// The first mainnet settlement (proposal 142135) trapped inside the CMC
// because block_index was encoded as `nat` where the CMC declares `nat64`
// (candid has no nat→nat64 subtyping), and the old NotifyError carried
// variants the real CMC never returns (AlreadyNotified / TransactionNotFound
// / InvalidTokenLedger) while missing real ones (Processing /
// InvalidTransaction) — so genuine CMC errors could not even be decoded.
// Wire compatibility is locked down by test_cmc_notify_wire_compat.
#[derive(CandidType, Serialize, Deserialize, Debug)]
pub struct NotifyTopUpArgs {
    pub canister_id: Principal,
    pub block_index: u64,
}

#[derive(CandidType, Serialize, Deserialize, Debug)]
pub enum NotifyTopUpResult {
    Ok(candid::Nat),
    Err(NotifyError),
}

#[derive(CandidType, Serialize, Deserialize, Debug)]
pub enum NotifyError {
    Refunded {
        block_index: Option<u64>,
        reason: String,
    },
    Processing,
    TransactionTooOld(u64),
    InvalidTransaction(String),
    Other {
        error_code: u64,
        error_message: String,
    },
}

#[derive(CandidType, Deserialize, Clone, Debug)]
pub enum BalanceResult {
    Ok(u64),
    Err(String),
}

#[cfg(target_arch = "wasm32")]
async fn call_ledger_balance(
    ledger_id: Principal,
    account: LedgerAccount,
) -> Result<u64, String> {
    let response: Result<(candid::Nat,), _> =
        ic_cdk::call(ledger_id, "icrc1_balance_of", (account,)).await;
    match response {
        Ok((balance,)) => {
            let bal_str = balance.to_string().replace('_', "");
            let bal_u64 = bal_str
                .parse::<u64>()
                .map_err(|e| format!("Failed to parse balance: {}", e))?;
            Ok(bal_u64)
        }
        Err((code, msg)) => {
            Err(format!("Ledger call failed (code {:?}): {}", code, msg))
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
thread_local! {
    static TEST_MOCK_LEDGER_BALANCE: RefCell<u64> = RefCell::new(0);
    static TEST_MOCK_LEDGER_TRANSFER: RefCell<Result<u64, String>> =
        RefCell::new(Ok(1));
    /// Opt-in accounting ledger for money-movement correctness tests (C3). When
    /// enabled, the native ledger mocks track per-account balances and a monotone
    /// block counter so a test can assert exact escrow/treasury/recipient effects.
    /// Disabled by default → existing tests keep the simple global-mock behavior.
    static TEST_ACCT_ENABLED: RefCell<bool> = const { RefCell::new(false) };
    static TEST_ACCT_BALANCES: RefCell<std::collections::HashMap<(Principal, [u8; 32]), u64>> =
        RefCell::new(std::collections::HashMap::new());
    static TEST_ACCT_NEXT_BLOCK: RefCell<u64> = const { RefCell::new(1) };
    /// When Some(err), the host `notify_cmc_topup` mock returns that Err instead of
    /// Ok — lets unit tests simulate a CMC notify failure (the C2 trapped-fund
    /// scenario) and assert the renew journaled the block + the sweep recovers it.
    static TEST_CMC_NOTIFY_FAIL: RefCell<Option<String>> = const { RefCell::new(None) };
    /// When Some(err), the host `xfarm_extend_farmer` mock returns that Err — lets
    /// unit tests simulate a Farmer `extend` failure (post-money renew error path).
    static TEST_XFARM_EXTEND_FAIL: RefCell<Option<String>> = const { RefCell::new(None) };
}

