        // 3. Any supported crypto funds it; raised is valued in USD.
        let funder = p("ryjl3-tyaaa-aaaaa-aaaba-cai");
        set_mock_caller(funder);
        set_mock_ledger_balance(10_000_000_000);
        set_mock_ledger_transfer(Ok(12));
